#include <linux/radix-tree.h>
#include <linux/mutex.h>
#include <linux/slab.h>
#include <linux/blkcg.h>

int blkcg_init_queue(struct request_queue *q)
{
    struct blkg_policy_data *pd;
    struct blkcg *blkcg;
    struct blkcg_gq *blkg;
    int ret;

    pd = kzalloc(sizeof(*pd), GFP_KERNEL);
    if (!pd)
        return -ENOMEM;

    blkg = &pd->blkg;
    blkg->q = q;
    blkg->pd[0] = pd;

    mutex_lock(&q->bd_mutex);
    ret = blkg_alloc(blkg);
    if (ret) {
        mutex_unlock(&q->bd_mutex);
        kfree(pd);
        return ret;
    }

    radix_tree_preload(GFP_KERNEL);
    mutex_lock(&q->bd_mutex);

    ret = blkg_register(blkg);
    if (ret) {
        blkg_free(blkg);
        mutex_unlock(&q->bd_mutex);
        radix_tree_preload_end();
        kfree(pd);
        return ret;
    }

    ret = blkg_init(blkg);
    if (ret) {
        blkg_unregister(blkg);
        blkg_free(blkg);
        mutex_unlock(&q->bd_mutex);
        radix_tree_preload_end();
        kfree(pd);
        return ret;
    }

    radix_tree_preload_end();
    mutex_unlock(&q->bd_mutex);

    return 0;
}

int blkcg_init_queue(struct request_queue *q)
{
    struct blkcg *root_blkg;
    struct blkg_policy_data *pd;
    int ret = 0;

    radix_tree_preload(GFP_KERNEL);
    root_blkg = kzalloc_node(sizeof(*root_blkg), GFP_KERNEL, q->node);
    if (!root_blkg) {
        ret = -ENOMEM;
        goto out_unload;
    }

    root_blkg->q = q;
    pd = blkg_alloc(&blkcg_policy_throttle, root_blkg, GFP_KERNEL);
    if (!pd) {
        ret = -ENOMEM;
        goto out_free_root;
    }

    root_blkg->pd[blkcg_pol_idx(&blkcg_policy_throttle)] = pd;
    if (blkcg_activate_policy(q, &blkcg_policy_throttle)) {
        ret = -ENOMEM;
        goto out_free_pd;
    }

    q->blkg_tree = &root_blkg->blkg_node;
    return 0;

out_free_pd:
    blkg_free(root_blkg, &blkcg_policy_throttle);
out_free_root:
    kfree(root_blkg);
out_unload:
    radix_tree_preload_end();
    return ret;
}

int blkcg_init_queue(struct request_queue *q)
{
    int ret;
    struct blkg_policy_data *pd;

    ret = radix_tree_preload(GFP_KERNEL);
    if (ret)
        return ret;

    pd = kzalloc_node(sizeof(*pd), GFP_KERNEL, q->node);
    if (!pd) {
        ret = -ENOMEM;
        goto out_unload;
    }

    pd->q = q;
    pd->blkg = kzalloc_node(sizeof(*pd->blkg), GFP_KERNEL, q->node);
    if (!pd->blkg) {
        ret = -ENOMEM;
        goto out_free_pd;
    }

    pd->blkg->q = q;
    pd->blkg->pd = pd;

    if (blkg_setup_accounting(pd->blkg)) {
        ret = -ENOMEM;
        goto out_free_blkg;
    }

    if (blkg_init_congestion(pd->blkg)) {
        ret = -ENOMEM;
        goto out_cleanup_accounting;
    }

    if (blkg_register(pd->blkg)) {
        ret = -ENOMEM;
        goto out_cleanup_congestion;
    }

    q->blkg = pd->blkg;

    return 0;

out_cleanup_congestion:
    blkg_cleanup_congestion(pd->blkg);
out_cleanup_accounting:
    blkg_clear_accounting(pd->blkg);
out_free_blkg:
    kfree(pd->blkg);
out_free_pd:
    kfree(pd);
out_unload:
    radix_tree_unload();
    return ret;
}
